        if (isset($this->vatAbsenceReason)) {
            $json['vatAbsenceReason']                  = VatAbsenceReasonEnum::checkValue($this->vatAbsenceReason);
        }
        if (isset($this->vatNumber)) {
            $json['vatNumber']                         = $this->vatNumber;
        }
        if (isset($this->webData)) {
            $json['webData']                           = $this->webData;
        }

        return (!$asArrayWhenEmpty && empty($json)) ? new stdClass() : $json;
    }
}
